contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Drive the contract: call SetMinSum while intitalized == false, then read MinSum.
    // For generality, take the value as a parameter.
    function check_SetMinSum_before_initialized(uint newMin) public {
        // Precondition: ensure the contract is not initialized by calling the Initialized getter indirectly is impossible,
        // so we rely on the external behavior: on the original contract (P) calling SetMinSum when not initialized should succeed.
        // Call the function that may revert on the mutant. This is the single state-changing call required.
        c.SetMinSum(newMin);

        // Observe the public MinSum value and assert it matches the provided parameter.
        uint observed = c.MinSum();
        assert(observed == newMin);
    }
}

