    // Drive the contract: set MinSum once before initialization, then initialize, then call SetMinSum again
    // Parameters: initial value a, second value b
    function check(uint a, uint b) public {
        // ensure we can call SetMinSum initially
        c.SetMinSum(a);
        // now initialize the contract so further SetMinSum should revert or not change MinSum in original
        c.Initialized();
        // record MinSum before the second SetMinSum
        uint before = c.MinSum();
        // attempt to call SetMinSum again after initialization
        // In original contract this will revert, so we capture the revert boolean using low-level call
        (bool ok, ) = address(c).call(abi.encodeWithSignature("SetMinSum(uint256)", b));
        // read MinSum after the attempt
        uint after = c.MinSum();
        // In the original contract, the second call is not allowed and MinSum remains equal to before.
        // In the mutant, SetMinSum would add b to MinSum even after initialization, so after == before would be violated.
        assert(after == before);
    }

    // allow the test contract to receive ETH if needed by c (not used here but kept minimal)
    receive() external payable {}
}

