import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz the initializer flag toggle (as a bool via uint) and the value to set
    function testFuzz_property(uint8 initializedFlag, uint256 newMin) public {
        // keep initializedFlag wide (0 or 1) by bounding to 0..1
        initializedFlag = uint8(bound(initializedFlag, 0, 1));

        // If initializedFlag == 1 we will call Initialized() before SetMinSum
        if (initializedFlag == 1) {
            c.Initialized();
        }

        bool ok;
        // call SetMinSum and capture whether it reverted or not
        try c.SetMinSum(newMin) {
            ok = true;
        } catch {
            ok = false;
        }

        // General rule: On the reference, SetMinSum succeeds iff intitalized==false,
        // and when it succeeds MinSum equals the provided newMin.
        // We assert the reference's observable consequence: if the call succeeded (ok==true)
        // then c.MinSum() == newMin; if the call reverted (ok==false) then c.MinSum()
        // must not have been changed by the call (for the reference this means it remains whatever it was before).
        // Because we only have one assertTrue allowed, we combine into a single predicate
        uint256 observed = c.MinSum();
        // If initializedFlag==0, reference should succeed and set MinSum==newMin.
        // If initializedFlag==1, reference should revert and MinSum should remain previous value (which is 0 since never set).
        // Build the expected condition accordingly and assert it.
        bool cond;
        if (initializedFlag == 0) {
            // call must succeed and MinSum must equal newMin
            cond = (ok == true && observed == newMin);
        } else {
            // initialized==1: call must revert and MinSum must remain unchanged (initially 0)
            cond = (ok == false && observed == 0);
        }

        assertTrue(cond);
    }
}

