pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz _lockTime and deposit amount and actor
    function testFuzz_property(uint256 _lockTime, uint256 deposit, address actor) public {
        // keep wide but sensible bounds for deposit and actor
        deposit = bound(deposit, 0, 1 ether);
        vm.assume(actor != address(0));

        // prepare actor with funds
        vm.deal(actor, deposit);
        // record prior unlockTime
        // ensure we can read the Holder.unlockTime via public mapping Acc - the compiler auto-generates Acc(address) -> (unlockTime,balance)
        (uint256 beforeUnlock,,) = _readHolder(actor);

        // perform Put from actor
        vm.prank(actor);
        c.Put{value: deposit}(_lockTime);

        // read after
        (uint256 afterUnlock,,) = _readHolder(actor);

        // The universal property: afterUnlock >= beforeUnlock and afterUnlock >= block.timestamp
        // Specifically the reference ensures unlockTime becomes max(prev, block.timestamp + _lockTime)
        // We assert monotonic non-decrease: afterUnlock >= beforeUnlock
        assertTrue(afterUnlock >= beforeUnlock);
    }

    // helper to read the generated getter for Acc mapping
    function _readHolder(address a) internal returns (uint256 unlockTime, uint256 balance, bool exists) {
        // The compiler generated getter for public mapping (address => Holder) public Acc;
        // has signature: function Acc(address) external view returns (uint unlockTime, uint balance);
        // But solidity may not return an exists flag; we return false for exists always (not used). Use low-level call to get two uints.
        (bool ok, bytes memory ret) = address(c).staticcall(abi.encodeWithSignature("Acc(address)", a));
        require(ok);
        (unlockTime, balance) = abi.decode(ret, (uint256, uint256));
        exists = true;
    }
}
